package mapping

import (
	"bytes"
	"path"
	"strings"
)

// generatedMarkers are the comments code generators put at the top of their output, matched in any case;
// "DO NOT EDIT" counts only in capitals, as generators write it, since authored comments say it too.
var generatedMarkers = []string{"code generated", "@generated", "auto-generated", "autogenerated"}

// GeneratedByHeader reports whether the first lines of src carry a code generator's marker.
func GeneratedByHeader(src []byte) bool {
	lines := bytes.SplitN(src, []byte("\n"), 6)
	for _, l := range lines[:min(5, len(lines))] {
		if bytes.Contains(l, []byte("DO NOT EDIT")) {
			return true
		}
		low := strings.ToLower(string(l))
		for _, m := range generatedMarkers {
			if strings.Contains(low, m) {
				return true
			}
		}
	}
	return false
}

// GeneratedByAttributes reports whether a root .gitattributes marks p linguist-generated; the last matching
// line wins, as in git. A pattern without a slash matches the base name; `**` is matched as one segment.
func GeneratedByAttributes(attrs []byte, p string) bool {
	out := false
	for _, line := range strings.Split(string(attrs), "\n") {
		fields := strings.Fields(line)
		if len(fields) < 2 || strings.HasPrefix(fields[0], "#") {
			continue
		}
		set, mentioned := false, false
		for _, a := range fields[1:] {
			switch a {
			case "linguist-generated", "linguist-generated=true":
				set, mentioned = true, true
			case "-linguist-generated", "linguist-generated=false", "!linguist-generated":
				set, mentioned = false, true
			}
		}
		if mentioned && attributeMatch(fields[0], p) {
			out = set
		}
	}
	return out
}

func attributeMatch(pattern, p string) bool {
	pattern = strings.TrimPrefix(pattern, "/")
	if !strings.Contains(pattern, "/") {
		ok, _ := path.Match(pattern, path.Base(p))
		return ok
	}
	for dir := p; dir != "." && dir != ""; dir = path.Dir(dir) {
		if ok, _ := path.Match(strings.TrimSuffix(pattern, "/**"), dir); ok {
			return true
		}
	}
	return false
}
